package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.nativerdf.ValueStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreWalBootstrapTailLossReviewTest {

	@TempDir
	Path directory;

	@Test
	void autoRecoveryPreservesHighestValueAfterSynchronousBootstrap() throws Exception {
		String classpath = System.getProperty("surefire.test.class.path", System.getProperty("java.class.path"));
		Path log = directory.resolve("bootstrap-tail-loss.log");
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		Process process = new ProcessBuilder(java, "-Xmx64m", "-XX:+ExitOnOutOfMemoryError", "-ea", "-cp", classpath,
				ValueStoreWalBootstrapTailLossReviewTest.class.getName(), directory.toString())
						.redirectErrorStream(true)
						.redirectOutput(log.toFile())
						.start();
		boolean exited;
		try {
			exited = process.waitFor(60, TimeUnit.SECONDS);
		} finally {
			if (process.isAlive()) {
				process.destroyForcibly();
				process.waitFor(10, TimeUnit.SECONDS);
			}
		}
		String output = Files.readString(log);
		assertThat(exited).withFailMessage("Bootstrap tail-loss probe timed out:%n%s", output).isTrue();
		assertThat(process.exitValue()).withFailMessage("Bootstrap tail-loss probe failed:%n%s", output).isZero();
	}

	public static void main(String[] args) throws Exception {
		Path directory = Path.of(args[0]);
		Path values = Files.createDirectory(directory.resolve("values"));
		Literal original = SimpleValueFactory.getInstance().createLiteral("\u6f22".repeat(900_000));
		int originalId;
		try (ValueStore store = new ValueStore(values.toFile())) {
			originalId = store.storeValue(original);
			store.sync();
		}
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(directory.resolve("wal"))
				.storeUuid("bootstrap-tail-loss-review")
				.syncBootstrapOnOpen(true)
				.recoverValueStoreOnOpen(true)
				.build();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config);
				ValueStore store = new ValueStore(values.toFile(), false, 16, 16, 16, 16, wal)) {
			if (!original.equals(store.getValue(originalId))) {
				throw new AssertionError("The original highest value is not readable before fixture data loss");
			}
			store.sync();
		}
		System.out.println("Synchronous bootstrap returned successfully for highest original ID " + originalId);

		// Simulate loss of exactly the fixture's dictionary files; leave every WAL segment intact.
		Files.delete(values.resolve("values.dat"));
		Files.delete(values.resolve("values.id"));
		Files.delete(values.resolve("values.hash"));
		try (ValueStoreWAL wal = ValueStoreWAL.open(config);
				ValueStore recovered = new ValueStore(values.toFile(), false, 16, 16, 16, 16, wal)) {
			recovered.checkConsistency();
			System.out.println("Automatic recovery opened successfully and its remaining dictionary is consistent");
			if (!original.equals(recovered.getValue(originalId))) {
				throw new AssertionError("Automatic recovery returned normally but lost highest original ID "
						+ originalId + " after successful synchronous bootstrap; no subsequent value was minted");
			}
		}
	}
}
